    r"^(?:(\d+(?:\.\d+)?)d)?(?:(\d+(?:\.\d+)?)h)?(?:(\d+(?:\.\d+)?)m)?(?:(\d+(?:\.\d+)?)s)?$"
)
_WORD_PATTERN = re.compile(
    r"^(?:\s*(\d+(?:\.\d+)?)\s*(days?|d)\b)?"
    r"(?:\s*(\d+(?:\.\d+)?)\s*(hours?|hrs?|h)\b)?"
    r"(?:\s*(\d+(?:\.\d+)?)\s*(?:minutes?|mins?|m)\b)?"
    r"(?:\s*(\d+(?:\.\d+)?)\s*(?:seconds?|secs?|s)\b)?\s*$",
    re.IGNORECASE,
)


def _to_seconds(groups, unit_offsets):
    total = 0.0
    for value, unit_index in zip(groups, unit_offsets):
        if value is None:
            continue
        unit = "dhms"[unit_index]
        factor = {"d": 86400, "h": 3600, "m": 60, "s": 1}[unit]
        total += float(value) * factor
    if total == 0.0:
        raise ValueError("empty duration")
    return total


def parse_duration(text):
    stripped = text.strip()
    symbol = _SYMBOL_PATTERN.fullmatch(stripped)
    if symbol and symbol.group(0):
        seconds = _to_seconds(symbol.groups(), range(4))
        return int(seconds) if seconds.is_integer() else seconds
    word = _WORD_PATTERN.fullmatch(text)
    if word and word.group(0).strip():
        # word pattern has optional whitespace groups interleaved: pick value groups
        values = (word.group(1), word.group(3), word.group(5), word.group(7))
        seconds = _to_seconds(values, range(4))
        return int(seconds) if seconds.is_integer() else seconds
    raise ValueError("invalid duration: %r" % (text,))


