    r"^(?:(\d+(?:\.\d+)?)d)?(?:(\d+(?:\.\d+)?)h)?(?:(\d+(?:\.\d+)?)m)?(?:(\d+(?:\.\d+)?)s)?$"
)
_WORD_PATTERN = re.compile(
    r"^(?:\s*(\d+(?:\.\d+)?)\s*(days?|d)\b)?"
    r"(?:\s*(\d+(?:\.\d+)?)\s*(hours?|hrs?|h)\b)?"
    r"(?:\s*(\d+(?:\.\d+)?)\s*(?:minutes?|mins?|m)\b)?"
    r"(?:\s*(\d+(?:\.\d+)?)\s*(?:seconds?|secs?|s)\b)?\s*$",
    re.IGNORECASE,
)


def _to_seconds(groups, unit_offsets):
    total = 0.0
    for value, unit_index in zip(groups, unit_offsets):
        if value is None:
            continue
        unit = "dhms"[unit_index]
        factor = {"d": 86400, "h": 3600, "m": 60, "s": 1}[unit]
        total += float(value) * factor
    if total == 0.0:
        raise ValueError("empty duration")
    return total


def parse_duration(text):
    stripped = text.strip()
    symbol = _SYMBOL_PATTERN.fullmatch(stripped)
    if symbol and symbol.group(0):
        seconds = _to_seconds(symbol.groups(), range(4))
        return int(seconds) if seconds.is_integer() else seconds
    word = _WORD_PATTERN.fullmatch(text)
    if word and word.group(0).strip():
        # word pattern has optional whitespace groups interleaved: pick value groups
        values = (word.group(1), word.group(3), word.group(5), word.group(7))
        seconds = _to_seconds(values, range(4))
        return int(seconds) if seconds.is_integer() else seconds
    raise ValueError("invalid duration: %r" % (text,))


def format_duration(seconds):
    """Turn whole seconds into the shortest string parse_duration accepts."""
    seconds = int(seconds)
    if seconds < 0:
        raise ValueError("negative duration")
    days, rem = divmod(seconds, 86400)
    hours, rem = divmod(rem, 3600)
    minutes, secs = divmod(rem, 60)
    parts = []
    if days:
        parts.append("%dd" % days)
    if hours:
        parts.append("%dh" % hours)
    if minutes:
        parts.append("%dm" % minutes)
    if secs or not parts:
        parts.append("%ds" % secs)
    return "".join(parts)


if __name__ == "__main__":
    import sys
    print(parse_duration(sys.argv[1]))


def _selftest():
    assert format_duration(5400) == "1h30m"
    assert format_duration(0) == "0s"
    assert format_duration(90061) == "1d1h1m1s"
    assert parse_duration(format_duration(7385)) == 7385
    assert parse_duration("1d1h1m1s") == 90061
    assert parse_duration("1 hour 30 minutes") == 5400
    assert parse_duration("2 hours") == 7200
    assert parse_duration("90 seconds") == 90
    assert parse_duration("1h30m") == 5400
    for bad in ("soon", ""):
        try:
            parse_duration(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(bad)


if __name__ == "__main__":
    _selftest()

