import sys

from durations import parse_duration, format_duration


def main():
    total = 0
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            total += parse_duration(line)
        except ValueError as exc:
            print(exc, file=sys.stderr)
            sys.exit(1)
    print(format_duration(total))


main()
